budget.value:
fun p =>
  have S := fun w => Finset.univ.sup' ⋯ fun j => ↑↑p.n * p.μ * w j - ∑ i, p.L i * max (w j - w i) 0;
  have W := fun w =>
    0 ≤ Finset.univ.inf' ⋯ w ∧ 1 ≤ S w ∧ 4096 * ↑↑p.n * p.ζ ^ 2 * ∑ i, (w i - (∑ j, w j) / ↑↑p.n) ^ 2 ≤ p.ε ^ 2;
  have V := fun v => ∑ i, ↑(p.h i) * v i ^ 2;
  have w := LongTails.Theorems.DistributedOptimumHeterogeneity.argmin W V;
  have u := fun i => ↑(p.h i) * w i;
  have M := Finset.univ.sup' ⋯ fun i => u i * p.L i;
  have κ := (2 * ∑ i, (↑(p.h i))⁻¹) * M;
  have G := Finset.univ.sup' ⋯ u * (p.σ + √↑↑p.n * p.ζ) / M;
  have q := ⌈2 + ↑p.d + κ + ((p.R + G) / p.ε) ^ 2⌉₊.size;
  (24576 * (p.σ ^ 2 * V w / p.ε ^ 2) +
      8192 * κ * (1 + Real.log (1 + (p.R / p.ε) ^ 2)) *
        (↑(Finset.univ.sup p.h) + ↑p.l + ↑p.b * (64 + 1024 * ↑p.d * ↑q))).toNNReal

